CREATE TABLE IF NOT EXISTS app_user(id BIGINT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(80) NOT NULL UNIQUE, password_hash VARCHAR(100), role VARCHAR(20) NOT NULL);
CREATE TABLE IF NOT EXISTS billiard_table(id BIGINT AUTO_INCREMENT PRIMARY KEY, table_no VARCHAR(20) NOT NULL UNIQUE, type VARCHAR(40) NOT NULL, status VARCHAR(20) NOT NULL, active_order_id BIGINT);
CREATE TABLE IF NOT EXISTS play_package(id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL, minutes INT NOT NULL, price DECIMAL(10,2) NOT NULL, enabled BOOLEAN NOT NULL);
CREATE TABLE IF NOT EXISTS play_order(id BIGINT AUTO_INCREMENT PRIMARY KEY, order_no VARCHAR(50) NOT NULL UNIQUE, request_key VARCHAR(80) NOT NULL UNIQUE, user_id BIGINT NOT NULL, table_id BIGINT NOT NULL, package_id BIGINT NOT NULL, package_name VARCHAR(80) NOT NULL, minutes INT NOT NULL, amount DECIMAL(10,2) NOT NULL, source VARCHAR(20) NOT NULL, payment_method VARCHAR(20) NOT NULL, status VARCHAR(20) NOT NULL, started_at TIMESTAMP NOT NULL, expected_end_at TIMESTAMP NOT NULL, ended_at TIMESTAMP, created_at TIMESTAMP NOT NULL, FOREIGN KEY(user_id) REFERENCES app_user(id), FOREIGN KEY(table_id) REFERENCES billiard_table(id), FOREIGN KEY(package_id) REFERENCES play_package(id));
CREATE TABLE IF NOT EXISTS operation_log(id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, action VARCHAR(50) NOT NULL, business_id BIGINT NOT NULL, created_at TIMESTAMP NOT NULL);

CREATE TABLE IF NOT EXISTS table_model(id BIGINT PRIMARY KEY, type VARCHAR(40) NOT NULL, brand VARCHAR(50) NOT NULL, model_name VARCHAR(80) NOT NULL, image_path VARCHAR(255), source_url VARCHAR(500));
CREATE TABLE IF NOT EXISTS package_price(scope_type VARCHAR(10) NOT NULL, scope_id BIGINT NOT NULL, package_id BIGINT NOT NULL, price DECIMAL(10,2) NOT NULL, PRIMARY KEY(scope_type,scope_id,package_id), FOREIGN KEY(package_id) REFERENCES play_package(id));
CREATE TABLE IF NOT EXISTS service_item(id BIGINT AUTO_INCREMENT PRIMARY KEY, kind VARCHAR(10) NOT NULL, brand VARCHAR(50) NOT NULL, name VARCHAR(100) NOT NULL, description VARCHAR(500) NOT NULL, rate DECIMAL(10,2) NOT NULL, stock INT NOT NULL, enabled BOOLEAN NOT NULL, source_url VARCHAR(500));
CREATE TABLE IF NOT EXISTS service_order(id BIGINT AUTO_INCREMENT PRIMARY KEY, request_key VARCHAR(80) NOT NULL UNIQUE, user_id BIGINT NOT NULL, item_id BIGINT NOT NULL, item_name VARCHAR(160) NOT NULL, kind VARCHAR(10) NOT NULL, rate DECIMAL(10,2) NOT NULL, status VARCHAR(20) NOT NULL, created_at TIMESTAMP NOT NULL, started_at TIMESTAMP, ended_at TIMESTAMP, billed_minutes INT, amount DECIMAL(10,2), FOREIGN KEY(user_id) REFERENCES app_user(id), FOREIGN KEY(item_id) REFERENCES service_item(id));
CREATE TABLE IF NOT EXISTS coach_grade(stars INT PRIMARY KEY, title VARCHAR(40) NOT NULL, rate DECIMAL(10,2) NOT NULL);
CREATE TABLE IF NOT EXISTS app_migration(id VARCHAR(80) PRIMARY KEY);
CREATE TABLE IF NOT EXISTS personal_history_hide(user_id BIGINT NOT NULL, record_kind VARCHAR(10) NOT NULL, record_id BIGINT NOT NULL, created_at TIMESTAMP NOT NULL, PRIMARY KEY(user_id,record_kind,record_id));

CREATE TABLE IF NOT EXISTS store_expense(id BIGINT AUTO_INCREMENT PRIMARY KEY, category VARCHAR(20) NOT NULL, expense_date DATE NOT NULL, amount DECIMAL(10,2) NOT NULL, note VARCHAR(200) NOT NULL, created_by BIGINT NOT NULL);

CREATE TABLE IF NOT EXISTS customer_profile(user_id BIGINT PRIMARY KEY,nickname VARCHAR(24) NOT NULL,age INT,gender VARCHAR(10) NOT NULL,FOREIGN KEY(user_id) REFERENCES app_user(id));
CREATE TABLE IF NOT EXISTS brand_store (
 id BIGINT AUTO_INCREMENT PRIMARY KEY,
 name VARCHAR(80) NOT NULL,
 province VARCHAR(40) NOT NULL,
 city VARCHAR(40) NOT NULL,
 address VARCHAR(180) NOT NULL,
 manager VARCHAR(40) NOT NULL,
 phone VARCHAR(32) NOT NULL
);
CREATE TABLE IF NOT EXISTS brand_store_month (
 store_id BIGINT NOT NULL,
 month_start DATE NOT NULL,
 revenue DECIMAL(14,2) NOT NULL,
 expenses DECIMAL(14,2) NOT NULL,
 PRIMARY KEY (store_id, month_start),
 FOREIGN KEY (store_id) REFERENCES brand_store(id)
);
CREATE TABLE IF NOT EXISTS membership_settings (
 id INT PRIMARY KEY,
 tiers_json VARCHAR(1600) NOT NULL
);
